j.update(round='candidate-v2',status='corrected draft awaiting final explicit ten-reviewer ratification',firstBallotSHA256=hashlib.sha256((ROOT/'candidates-v1.json').read_bytes()).hexdigest(),corrections=changes)
assert not (ROOT/'candidates-v2.json').exists();(ROOT/'candidates-v2.json').write_text(json.dumps(j,indent=2)+'\n')
(ROOT/'consensus/correction-ledger.json').write_text(json.dumps({'schema':1,'firstVotes':votes,'resolutions':changes,'candidateV2SHA256':hashlib.sha256((ROOT/'candidates-v2.json').read_bytes()).hexdigest(),'acceptance':'No native or baseline acceptance; export15 deliberately deferred.'},indent=2)+'\n')
# Preserve original first-ballot philosophy; make a fresh revised name and doctrine.
s=(ROOT/'PHILOSOPHY-V1.md').read_text().replace('Accord','Aletheia')
s=s.replace('It names the agreement between user intent, visible state and native behavior. Naming remains a proposal pending the user\'s preference.','The Greek word means truth; the name evokes disclosure and intelligibility. The user requested an esoteric name; this is the working proposal. [Greek lexicon](https://atlas.perseus.tufts.edu/dictionaries/headword/%E1%BC%80%CE%BB%CE%AE%CE%B8%CE%B5%CE%B9%CE%B1/).')
s=s.replace('People should be able to act without wondering which window will receive a click or whether an action succeeded.','People should know which window receives an action and whether its outcome is confirmed, refused or still unconfirmed.')
s=s.replace('Maintain a single authoritative model of ordinary shell policy. Derive surfaces from it, make state changes explicit and keep effect descriptions inspectable.','Maintain one controller model of user intent and ordinary UI policy, with native facts held as read-only observations of native authority. Derive surfaces from it, make state changes explicit and keep effect descriptions inspectable.')
s=s.replace('requested, committed, presented and unconfirmed','requested, committed, refused, cancelled, presented and unconfirmed')
s=s.replace('Preserve independent controls and avoid replaying uncertain operations automatically.','Preserve independent controls and never automatically replay Unknown or uncertain operations; reconcile with native truth first.')
s=s.replace('Keep control identity, selection and focus stable when unrelated state changes.','Keep control identity stable through unrelated changes, and preserve eligible selection and focus as distinct states.')
s=s.replace('Qualify the native route, including constrained geometry, text enlargement and composition.','Qualify the native route, including constrained geometry, text enlargement and composition. Announcements reach the user once under the frozen attention policy, without moving focus.')
s=s.replace('Keep queues, retained history, captures and diagnostic records bounded.','Keep queues, retained history, captures and diagnostic records bounded through explicit admission and proof-safe reclamation. Never forget unresolved outcomes, cleanup obligations or replay floors to make space.')
s=s.replace('Suspend unnecessary recurring work when no consumer needs it.','Pace visible-consumer work under a frozen policy and suspend unnecessary recurring work when no consumer needs it. Diagnostics contain only allowlisted facts, never secrets, draft content or pixels, and never act as authority.')
s=s.replace('Continuity/accessibility:012,016–020,023,029,030.','Continuity/accessibility:012,016–020,023,029,030.')
s=s.replace('convergence draft','corrected convergence draft')
(ROOT/'PHILOSOPHY-V2.md').write_text(s)
print(json.dumps({'candidates':len(rows),'scenarios':sum(len(r['scenarios']) for r in rows),'corrections':len(changes),'firstReviewers':len(votes)}))
